const SCR=new Map();let RAF=0;document.addEventListener('scroll',(e)=>{const x=e.target;if(!x||x===document||!x.id)return;if(x.scrollTop||x.scrollLeft)SCR.set(x.id,[x.scrollTop,x.scrollLeft]);else SCR.delete(x.id)},true);
