function uxMeCards() { const d = document.createElement('div'); d.innerHTML = pgMe(); return [...d.children]; }
const uxIsSet = (c) => /\u81EA\u8BA2\u7B56\u7565|\u5FEB\u901F\u4E70\u5356\u8BBE\u5B9A/.test(c.querySelector?.('h4')?.textContent || '');
