/* \u2500\u2500 PSE-1103 \u{1F3AF} \u81EA\u8BA2\u7B56\u7565\uFF1A\u624B\u673A\u53EF\u4EE5\u770B\u3001\u4E5F\u53EF\u4EE5\u6539\uFF08\u7ECF\u7531\u52A0\u5BC6\u8F6C\u63A5\u9001\u5230\u7535\u8111\uFF1B\u7535\u8111\u7528\u8DDF\u8BBE\u5B9A\u9875\u540C\u4E00\u5957\u68C0\u67E5\uFF0C\u901A\u8FC7\u624D\u5199\u8FDB\u540C\u4E00\u4EFD\u8BBE\u5B9A\u6863\uFF09\u2500\u2500
   \u7A0B\u5F0F\u91CC\u6CA1\u6709\u4EFB\u4F55\u4E70\u5356\u6570\u5B57\uFF1A\u680F\u4F4D\u7A7A\u7684\u5C31\u662F\u7A7A\u7684\uFF0C\u7070\u8272\u5B57\u53EA\u662F\u63D0\u793A\u3002\u94B1\u5305\u3001\u9080\u8BF7\u7801\u3001TG\u3001\u624B\u673A\u8FDE\u7ED3\uFF0F\u8F6C\u63A5\u7AD9\u7684\u8BBE\u5B9A\uFF0C\u624B\u673A\u770B\u4E0D\u5230\u4E5F\u6539\u4E0D\u4E86\u3002 */
const SE = { on: false, d: null, at: 0, g: '', draft: {}, fok: new Set(), err: '', busy: 0, sig: '' };
const SE_STALE = 5 * 60e3; /* \u8FD0\u4F5C\u5E38\u6570\uFF1A\u8BBE\u5B9A\u8D44\u6599\u8D85\u8FC7 5 \u5206\u949F\u6CA1\u66F4\u65B0\u5C31\u5148\u91CD\u65B0\u8F7D\u5165\uFF0C\u514D\u5F97\u76D6\u6389\u7535\u8111\u4E0A\u521A\u6539\u7684 */
const seIt = (k) => (SE.d?.items || []).find((x) => x.k === k);
const seVal = (k) => (k in SE.draft ? SE.draft[k] : SE.d?.vals?.[k]);
function seOnV(it, v) { if (v == null || v === '') return !!it?.floor; return v === true || +v === 1; }
