  const dl = ST?.ref?.ave ? '<div style="padding:0 4px 8px"><a data-ely-dl="1" style="color:var(--gold,#f0b90b);font-size:12.5px">\u8FD8\u6CA1\u88C5 AVE\uFF1F\u4E0B\u8F7D \xB7 Get AVE</a></div>' : '';
