  const st = D.st || {}; const M = { ok: '\u76D1\u6D4B\u4E2D\uFF08\u53EA\u8BFB\uFF09', catch: '\u6B63\u5728\u8865\u533A\u5757', start: '\u8FDE\u7EBF\u4E2D\u2026', err: '\u8BFB\u4E0D\u5230', badchain: '\u5DF2\u505C\u6B62\uFF1A\u94FE\u7F16\u53F7\u4E0D\u5BF9', norpc: '\u6CA1\u6709\u53EF\u7528\u7684\u8282\u70B9', off: '\u5173\u7740' };
